from PIL import Image
def patch(f,x0,x1,y0,y1):
    im=Image.open(f"/home/robot/captures/{f}.jpg").convert("L").resize((640*4,480*4),Image.BICUBIC)
    return im.load()
def shift(pa,pb,x0,x1,y0,y1,ymax=6):
    best=None
    for dy4 in range(-4*ymax,4*ymax+1):
        s=n=0
        for y in range(y0*4,y1*4):
            y2=y+dy4
            if y2<0 or y2>=480*4: continue
            for x in range(x0*4,x1*4):
                s+=(pa[x,y]-pb[x,y2])**2; n+=1
        v=s/n
        if best is None or v<best[1]: best=(dy4,v)
    # parabolic refine
    return best
pairs=[("side_008","side_009"),("side_007","side_009"),("side_006","side_009")]
regions={"cup_left":(292,300,240,256),"guard_right":(341,352,240,256),"coil_bottom":(305,335,246,256)}
for f1,f2 in pairs:
    pa=patch(f1,0,0,0,0); pb=patch(f2,0,0,0,0)
    for name,(x0,x1,y0,y1) in regions.items():
        dy,v=shift(pa,pb,x0,x1,y0,y1)
        print(f1,name,"dy=%.2fpx"%(dy/4))
EOF

